def _move_existing_data() -> None:
    """1·2단계 데이터를 "기존 데이터 센터"로 옮긴다.

    모든 사용자를 요양보호사로, 모든 수급자를 그 센터로 옮기고 모든 사용자 × 수급자에 배정을 만든다.
    기존 수급자에는 건강정보 처리 동의도 만든다. 데이터가 전부 가상이라 가능한 처리다.
    운영 데이터라면 동의를 자동으로 만들면 안 되고, 센터가 받은 동의서를 보고 기록해야 한다.
    """
    conn = op.get_bind()
    has_rows = conn.execute(
        sa.text("SELECT EXISTS (SELECT 1 FROM users) OR EXISTS (SELECT 1 FROM recipients)")
    ).scalar()
    if not has_rows:
        return
    org_id = conn.execute(
        sa.text(
            "INSERT INTO organizations (id, name) VALUES (gen_random_uuid(), '기존 데이터 센터') "
            "RETURNING id"
        )
    ).scalar()
    conn.execute(sa.text("UPDATE users SET org_id = :org, role = 'caregiver'"), {"org": org_id})
    conn.execute(sa.text("UPDATE recipients SET org_id = :org"), {"org": org_id})
    conn.execute(
        sa.text(
            "INSERT INTO assignments (id, recipient_id, caregiver_id, created_by) "
            "SELECT gen_random_uuid(), r.id, u.id, u.id FROM recipients r CROSS JOIN users u"
        )
    )
    # 기록한 사람이 있어야 해서 가장 먼저 가입한 사용자를 기록자로 둔다
    conn.execute(
        sa.text(
            "INSERT INTO consents (id, recipient_id, kind, granted_on, recorded_by) "
            "SELECT gen_random_uuid(), r.id, 'health_record', CURRENT_DATE, "
            "(SELECT id FROM users ORDER BY created_at, id LIMIT 1) "
            "FROM recipients r WHERE EXISTS (SELECT 1 FROM users)"
        )
    )


